## Debounce Function in JavaScript

### Implementation

```javascript
/**
 * Creates a debounced version of the provided function that delays invoking
 * the function until after `delay` milliseconds have elapsed since the last
 * time the debounced function was invoked.
 *
 * @param {Function} func - The function to debounce
 * @param {number} delay - The number of milliseconds to delay
 * @param {Object} options - Configuration options
 * @param {boolean} options.leading - Invoke on the leading edge of the timeout (default: false)
 * @param {boolean} options.trailing - Invoke on the trailing edge of the timeout (default: true)
 * @returns {Function} - The debounced function
 */
function debounce(func, delay, { leading = false, trailing = true } = {}) {
  if (typeof func !== "function") {
    throw new TypeError("Expected a function");
  }

  if (typeof delay !== "number" || delay < 0) {
    throw new RangeError("Delay must be a non-negative number");
  }

  let timeoutId = null;
  let lastResult;

  const debounced = function (...args) {
    const context = this;
    const shouldCallLeading = leading && !timeoutId;

    // Clear the existing timeout on every call
    clearTimeout(timeoutId);

    timeoutId = setTimeout(() => {
      timeoutId = null;

      if (trailing && !shouldCallLeading) {
        lastResult = func.apply(context, args);
      }
    }, delay);

    // Invoke immediately on the leading edge if configured
    if (shouldCallLeading) {
      lastResult = func.apply(context, args);
    }

    return lastResult;
  };

  // Cancel any pending invocation
  debounced.cancel = () => {
    clearTimeout(timeoutId);
    timeoutId = null;
  };

  // Check if there is a pending invocation
  debounced.isPending = () => timeoutId !== null;

  // Immediately invoke any pending invocation
  debounced.flush = function (...args) {
    if (timeoutId) {
      clearTimeout(timeoutId);
      timeoutId = null;
      lastResult = func.apply(this, args);
    }
    return lastResult;
  };

  return debounced;
}
```

