### When to Use Debounce

- **Search inputs** – Wait until the user stops typing before fetching results
- **Window resize** – Recalculate layout only after resizing stops
- **Form validation** – Validate after the user pauses input
- **Button clicks** – Prevent accidental double submissions

## Debounce Function in JavaScript

### Implementation

```javascript
/**
 * Creates a debounced version of a function that delays invoking the function
 * until after the specified delay has elapsed since the last invocation.
 *
 * @param {Function} func - The function to debounce
 * @param {number} delay - The delay in milliseconds
 * @param {Object} options - Optional configuration
 * @param {boolean} options.leading - Invoke on the leading edge of the timeout (default: false)
 * @param {boolean} options.trailing - Invoke on the trailing edge of the timeout (default: true)
 * @returns {Function} The debounced function
 */
function debounce(func, delay, options = {}) {
  const { leading = false, trailing = true } = options;

  let timeoutId = null;
  let lastArgs = null;
  let lastThis = null;
  let result = null;

  function invokeFunc() {
    result = func.apply(lastThis, lastArgs);
    lastArgs = null;
    lastThis = null;
    return result;
  }

  function debounced(...args) {
    lastArgs = args;
    lastThis = this;

    const isFirstCall = timeoutId === null;

    // Clear the existing timeout
    clearTimeout(timeoutId);

    // Invoke on the leading edge if configured
    if (leading && isFirstCall) {
      invokeFunc();
    }

    // Set a new timeout for the trailing edge
    timeoutId = setTimeout(() => {
      timeoutId = null;

      if (trailing && !isFirstCall) {
        invokeFunc();
      } else if (trailing && isFirstCall && !leading) {
        invokeFunc();
      }
    }, delay);

    return result;
  }

  /**
   * Cancels any pending debounced invocation
   */
  debounced.cancel = function () {
    clearTimeout(timeoutId);
    timeoutId = null;
    lastArgs = null;
    lastThis = null;
  };

  /**
   * Immediately invokes the debounced function if there's a pending call
   */
  debounced.flush = function () {
    if (timeoutId !== null) {
      clearTimeout(timeoutId);
      timeoutId = null;
      invokeFunc();
    }
    return result;
  };

  /**
   * Returns whether there is a pending invocation
   */
  debounced.isPending = function () {
    return timeoutId !== null;
  };

  return debounced;
}
