```javascript
/**
 * Parses a URL query string into an object.
 * @param {string} queryString - The query string to parse (with or without leading '?')
 * @returns {Object} - Parsed key-value pairs
 */
function parseQueryString(queryString) {
  if (!queryString || typeof queryString !== "string") {
    return {};
  }

  // Remove leading '?' or '#' if present
  const query = queryString.replace(/^[?#]/, "");

  if (!query) {
    return {};
  }

  return query.split("&").reduce((params, pair) => {
    const [rawKey, rawValue = ""] = pair.split("=");

    // Skip empty keys
    if (!rawKey) return params;

    const key = decodeURIComponent(rawKey.trim());
    const value = decodeURIComponent(rawValue.trim());

    // Handle duplicate keys → convert to array
    if (Object.prototype.hasOwnProperty.call(params, key)) {
      params[key] = Array.isArray(params[key])
        ? [...params[key], value]
        : [params[key], value];
    } else {
      params[key] = value;
    }

    return params;
  }, {});
}
```

