### 2. The Classic Way: Using Recursion

This is a common interview question and a great way to understand the logic behind flattening. The function processes each element: if it's an array, it calls itself on that element; otherwise, it adds the element to the result.

```javascript
/**
 * Flattens a nested array using recursion.
 * @param {Array} arr The array to flatten.
 * @returns {Array} The new flattened array.
 */
function flattenWithRecursion(arr) {
  let flattened = [];

  for (const element of arr) {
    if (Array.isArray(element)) {
      // If the element is an array, recursively flatten it and concatenate the result
      flattened = flattened.concat(flattenWithRecursion(element));
    } else {
      // If the element is not an array, just push it
      flattened.push(element);
    }
  }

  return flattened;
}


