      timeoutId = null; // Reset after the delay has passed

      // If it's not a leading-edge call, execute it at the end (trailing edge)
      if (!leading) {
        func.apply(context, args);
      }
    }, delay);

    // If it's a leading-edge call, execute it immediately
    if (isLeadingCall) {
      func.apply(context, args);
    }
  };
}

