    const context = this;

    // This function will be executed after the delay
    const later = function() {
      // Clear the timeout ID so that a new timeout can be set on the next call
      timeoutId = null;
      // If not immediate, execute the original function after the delay
      if (!immediate) {
        func.apply(context, args);
      }
    };

    // Determine if we should call the function immediately
    const callNow = immediate && !timeoutId;

    // Clear the previous timeout to reset the waiting period
    clearTimeout(timeoutId);

    // Set a new timeout
    timeoutId = setTimeout(later, delay);

    // If `immediate` is true and there's no existing timeout, call the function now
    if (callNow) {
      func.apply(context, args);
    }
  };
}
```

