  let timeoutId;

  // Return a new function that will be the one actually called
  return function(...args) {
    // `this` refers to the context in which the debounced function was called
    const context = this;

    // 1. Clear the previous timeout on every new call
    clearTimeout(timeoutId);

    // 2. Set a new timeout
    timeoutId = setTimeout(() => {
      // 3. When the timeout completes, call the original function
      //    with the correct context (`this`) and arguments
      func.apply(context, args);
    }, delay);
  };
}
