### Method 1: The Modern, Recommended Approach (using `URLSearchParams`)

This is the best practice for modern browsers and Node.js environments. The `URLSearchParams` API is specifically designed for this task, making it robust, reliable, and easy to use.

```javascript
/**
 * Parses a query string into an object.
 * This modern approach uses the built-in URLSearchParams API.
 * It correctly handles multiple values for the same key by creating an array.
 *
 * @param {string} queryString The query string to parse (e.g., "?name=John&age=30").
 * @returns {object} An object representing the parsed query string.
 */
function parseQueryString(queryString) {
  // If the input is empty or not a string, return an empty object.
  if (!queryString || typeof queryString !== 'string') {
    return {};
  }

  // URLSearchParams handles the leading '?' automatically.
  const params = new URLSearchParams(queryString);
  const result = {};

  // Iterate over all key-value pairs.
  for (const [key, value] of params.entries()) {
    // If the key already exists, it means we have multiple values.
    if (result.hasOwnProperty(key)) {
      // If it's not already an array, convert it to one.
      if (!Array.isArray(result[key])) {
        result[key] = [result[key]];
      }
      // Push the new value.
      result[key].push(value);
    } else {
      // Otherwise, just set the value.
      result[key] = value;
    }
  }

  return result;
}

// --- Examples ---
const url1 = "?name=John%20Doe&age=30&city=New%20York";
console.log(parseQueryString(url1));
// Output: { name: 'John Doe', age: '30', city: 'New York' }

const url2 = "tag=javascript&tag=webdev&level=intermediate";
console.log(parseQueryString(url2));
// Output: { tag: [ 'javascript', 'webdev' ], level: 'intermediate' }

const url3 = "?isAdmin&user=";
console.log(parseQueryString(url3));
// Output: { isAdmin: '', user: '' }

const url4 = "";
console.log(parseQueryString(url4));
// Output: {}
```

