If you need to support older browsers or want to handle features like duplicate keys by creating arrays, a custom function is the way to go. This is a great exercise for understanding the mechanics of parsing.

This version handles:
*   A leading `?`.
*   URL-encoded characters (like `%20` for space).
*   Keys with no values (e.g., `isAdmin`).
*   Duplicate keys by creating an array of values.

```javascript
/**
 * Parses a query string into an object from scratch.
 * Handles duplicate keys by creating an array of values.
 * @param {string} queryString - The string to parse.
 * @returns {object} An object representing the query string.
 */
function parseQueryString(queryString) {
  // 1. Return an empty object if the input is invalid
  if (!queryString || typeof queryString !== 'string') {
    return {};
  }

  // 2. Remove the leading '?' if it exists
  const cleanString = queryString.startsWith('?') ? queryString.slice(1) : queryString;

  // 3. If the string is empty after cleaning, return {}
  if (!cleanString) {
    return {};
  }

  const result = {};

  // 4. Split the string into key-value pairs
  const pairs = cleanString.split('&');

  // 5. Iterate over each pair
  for (const pair of pairs) {
    // Use indexOf to handle cases where the value might contain '='
    const eqIndex = pair.indexOf('=');
    const key = eqIndex > -1 ? pair.substring(0, eqIndex) : pair;
    const value = eqIndex > -1 ? pair.substring(eqIndex + 1) : true; // Key with no value is true

    // Skip empty keys, e.g., from "&&" or "&="
    if (!key) continue;

    // Decode URI components for both key and value
    const decodedKey = decodeURIComponent(key);
    const decodedValue = typeof value === 'string' ? decodeURIComponent(value.replace(/\+/g, ' ')) : value;

    // 6. Handle duplicate keys
    if (result.hasOwnProperty(decodedKey)) {
      // If the key already exists, convert it to an array or push to it
      if (Array.isArray(result[decodedKey])) {
        result[decodedKey].push(decodedValue);
      } else {
        result[decodedKey] = [result[decodedKey], decodedValue];
      }
    } else {
      // Otherwise, just add the key-value pair
      result[decodedKey] = decodedValue;
    }
  }

  return result;
}


