function parseQueryString(queryString) {
  // 1. If the query string is empty or not a string, return an empty object.
  if (!queryString || typeof queryString !== 'string') {
    return {};
  }

  // 2. Remove the leading '?' if it exists.
  const cleanString = queryString.startsWith('?') ? queryString.slice(1) : queryString;

  // If the string is empty after cleaning, return empty object.
  if (!cleanString) {
    return {};
  }

  const result = {};

  // 3. Split the string into key-value pairs.
  const pairs = cleanString.split('&');

  // 4. Iterate over each pair.
  for (const pair of pairs) {
    // Handle cases like 'a=1&&b=2' (empty pair)
    if (!pair) continue;

    // 5. Split the pair into a key and value.
    // Using indexOf to handle keys without values (e.g., 'isAdmin')
    const eqIndex = pair.indexOf('=');
    let key, value;

    if (eqIndex === -1) {
      // No '=' found, the key is the whole pair
      key = pair;
      value = ''; // Assign an empty string or true, depending on desired behavior
    } else {
      // '=' found, split into key and value
      key = pair.substring(0, eqIndex);
      value = pair.substring(eqIndex + 1);
    }

    // 6. Decode the key and value to handle URL-encoded characters like %20 or +.
    // The replace(/\+/g, ' ') is for legacy encodings where spaces are '+'
    const decodedKey = decodeURIComponent(key.replace(/\+/g, ' '));
    const decodedValue = decodeURIComponent(value.replace(/\+/g, ' '));

    // 7. Add the key-value pair to the result object.
    // If the key already exists, convert its value to an array and push the new value.
    if (result.hasOwnProperty(decodedKey)) {
      // If it's not already an array, make it one
      if (!Array.isArray(result[decodedKey])) {
        result[decodedKey] = [result[decodedKey]];
      }
      result[decodedKey].push(decodedValue);
    } else {
      result[decodedKey] = decodedValue;
    }
  }

  return result;
}

